public class Main {
    enum Status { OK, DECLINED, ERROR }

    // The interface our own code depends on.
    interface PaymentProcessor { Status pay(int orderId, int rupees); }

    // Vendor SDK we cannot change: paise, string codes.
    static class BankSdk {
        String makeTransfer(String ref, long paise, String currency) {
            return paise > 10000000L ? "51" : "00";
        }
    }

    // Object adapter: holds the SDK (composition) and translates both ways.
    static class BankAdapter implements PaymentProcessor {
        private final BankSdk sdk = new BankSdk();
        public Status pay(int orderId, int rupees) {
            String code = sdk.makeTransfer("ORD-" + orderId, rupees * 100L, "INR"); // rupees -> paise
            switch (code) {                                                          // code -> enum
                case "00": return Status.OK;
                case "51": return Status.DECLINED;
                default: return Status.ERROR;
            }
        }
    }

    public static void main(String[] args) {
        PaymentProcessor p = new BankAdapter();
        System.out.println("order 7, Rs 250 -> " + p.pay(7, 250));
        System.out.println("order 8, Rs 150000 -> " + p.pay(8, 150000));
    }
}

