#include <bits/stdc++.h>
using namespace std;

enum class Status { OK, DECLINED, ERROR };
const char* name(Status s) {
    return s == Status::OK ? "OK" : s == Status::DECLINED ? "DECLINED" : "ERROR";
}

// The interface our own code depends on.
struct PaymentProcessor {
    virtual Status pay(int orderId, int rupees) = 0;
    virtual ~PaymentProcessor() = default;
};

// Vendor SDK we cannot change: paise, string codes.
struct BankSdk {
    string makeTransfer(const string& ref, long long paise, const string& cur) {
        return paise > 10000000LL ? "51" : "00";
    }
};

// Object adapter: holds the SDK (composition) and translates both ways.
class BankAdapter : public PaymentProcessor {
    BankSdk sdk;
public:
    Status pay(int orderId, int rupees) override {
        string code = sdk.makeTransfer("ORD-" + to_string(orderId), rupees * 100LL, "INR"); // rupees -> paise
        if (code == "00") return Status::OK;                                                // code -> enum
        if (code == "51") return Status::DECLINED;
        return Status::ERROR;
    }
};

int main() {
    BankAdapter p;
    cout << "order 7, Rs 250 -> " << name(p.pay(7, 250)) << endl;
    cout << "order 8, Rs 150000 -> " << name(p.pay(8, 150000)) << endl;
}

