using System;

class Program
{
    enum Status { OK, DECLINED, ERROR }

    // The interface our own code depends on.
    interface IPaymentProcessor { Status Pay(int orderId, int rupees); }

    // Vendor SDK we cannot change: paise, string codes.
    class BankSdk
    {
        public string MakeTransfer(string reference, long paise, string currency)
        {
            return paise > 10000000L ? "51" : "00";
        }
    }

    // Object adapter: holds the SDK (composition) and translates both ways.
    class BankAdapter : IPaymentProcessor
    {
        private readonly BankSdk sdk = new BankSdk();
        public Status Pay(int orderId, int rupees)
        {
            string code = sdk.MakeTransfer("ORD-" + orderId, rupees * 100L, "INR"); // rupees -> paise
            if (code == "00") return Status.OK;                                      // code -> enum
            if (code == "51") return Status.DECLINED;
            return Status.ERROR;
        }
    }

    static void Main()
    {
        IPaymentProcessor p = new BankAdapter();
        Console.WriteLine("order 7, Rs 250 -> " + p.Pay(7, 250));
        Console.WriteLine("order 8, Rs 150000 -> " + p.Pay(8, 150000));
    }
}

