public class Main {
    interface Coffee { String desc(); int cost(); }

    static class Espresso implements Coffee {
        public String desc() { return "Espresso"; }
        public int cost() { return 50; }
    }
    static class Latte implements Coffee {
        public String desc() { return "Latte"; }
        public int cost() { return 60; }
    }

    // Decorators implement the same interface, hold one inner Coffee, add a little, delegate.
    static class Milk implements Coffee {
        private final Coffee inner;
        Milk(Coffee inner) { this.inner = inner; }
        public String desc() { return inner.desc() + "+Milk"; }
        public int cost() { return inner.cost() + 10; }
    }
    static class Sugar implements Coffee {
        private final Coffee inner;
        Sugar(Coffee inner) { this.inner = inner; }
        public String desc() { return inner.desc() + "+Sugar"; }
        public int cost() { return inner.cost() + 5; }
    }

    public static void main(String[] args) {
        Coffee a = new Sugar(new Milk(new Espresso())); // choose combination at run time
        Coffee b = new Sugar(new Latte());
        System.out.println(a.desc() + " cost=" + a.cost());
        System.out.println(b.desc() + " cost=" + b.cost());
        int coffees = 3, addOns = 5;
        // Subclassing needs one class per subset of add-ons; decorators need one per add-on.
        System.out.println("subclasses=" + coffees * (1 << addOns) + " decorator classes=" + (coffees + addOns));
    }
}

