public class Main {
    interface Notifier { String send(String msg); }

    static class Console implements Notifier {
        public String send(String msg) { return "send:" + msg; }
    }

    // Legacy class with a DIFFERENT interface.
    static class LegacySms { String push(String text, int priority) { return "SMS[prio=" + priority + "] " + text; } }

    // ADAPTER: translates push(...) into send(...).
    static class SmsAdapter implements Notifier {
        private final LegacySms sms = new LegacySms();
        public String send(String msg) { return sms.push(msg, 1); }
    }

    // DECORATOR: same interface, ADDS behaviour (upper-casing).
    static class Shout implements Notifier {
        private final Notifier inner;
        Shout(Notifier inner) { this.inner = inner; }
        public String send(String msg) { return inner.send(msg.toUpperCase()); }
    }

    // PROXY: same interface, same behaviour, CONTROLS access.
    static class Guard implements Notifier {
        private final Notifier inner; private final boolean allowed;
        Guard(Notifier inner, boolean allowed) { this.inner = inner; this.allowed = allowed; }
        public String send(String msg) { return allowed ? inner.send(msg) : "DENIED"; }
    }

    public static void main(String[] args) {
        System.out.println("adapter: " + new SmsAdapter().send("hello"));
        System.out.println("decorator: " + new Shout(new Console()).send("hello"));
        System.out.println("proxy allowed: " + new Guard(new Console(), true).send("hello"));
        System.out.println("proxy denied: " + new Guard(new Console(), false).send("hello"));
    }
}

