#include <bits/stdc++.h>
using namespace std;

struct Notifier {
    virtual string send(const string& msg) = 0;
    virtual ~Notifier() = default;
};
struct ConsoleNotifier : Notifier {
    string send(const string& msg) override { return "send:" + msg; }
};

// Legacy class with a DIFFERENT interface.
struct LegacySms {
    string push(const string& text, int priority) { return "SMS[prio=" + to_string(priority) + "] " + text; }
};

// ADAPTER: translates push(...) into send(...).
struct SmsAdapter : Notifier {
    LegacySms sms;
    string send(const string& msg) override { return sms.push(msg, 1); }
};

// DECORATOR: same interface, ADDS behaviour (upper-casing).
struct Shout : Notifier {
    Notifier& inner;
    Shout(Notifier& n) : inner(n) {}
    string send(const string& msg) override {
        string up = msg;
        for (auto& c : up) c = toupper(c);
        return inner.send(up);
    }
};

// PROXY: same interface, same behaviour, CONTROLS access.
struct Guard : Notifier {
    Notifier& inner; bool allowed;
    Guard(Notifier& n, bool a) : inner(n), allowed(a) {}
    string send(const string& msg) override { return allowed ? inner.send(msg) : "DENIED"; }
};

int main() {
    ConsoleNotifier c; SmsAdapter ad; Shout sh(c); Guard ok(c, true), no(c, false);
    cout << "adapter: " << ad.send("hello") << endl;
    cout << "decorator: " << sh.send("hello") << endl;
    cout << "proxy allowed: " << ok.send("hello") << endl;
    cout << "proxy denied: " << no.send("hello") << endl;
}

