public class Main {
    // Subsystems: they know nothing about the facade.
    static class Inventory {
        void reserve(String item) { System.out.println("  reserve " + item); }
        void release(String item) { System.out.println("  release " + item); }
    }
    static class Payment {
        boolean charge(int amount) { boolean ok = amount <= 1000; System.out.println("  charge " + amount + (ok ? " ok" : " declined")); return ok; }
    }
    static class Shipping { void ship(String item) { System.out.println("  ship " + item); } }
    static class Email { void confirm(String item) { System.out.println("  email confirmation for " + item); } }

    // Facade: one simple call that coordinates the subsystems, with compensation.
    static class OrderFacade {
        private final Inventory inv = new Inventory(); private final Payment pay = new Payment();
        private final Shipping ship = new Shipping(); private final Email mail = new Email();
        String placeOrder(String item, int amount) {
            inv.reserve(item);
            if (!pay.charge(amount)) { inv.release(item); return "FAILED"; } // undo on failure
            ship.ship(item);
            mail.confirm(item);
            return "PLACED";
        }
    }

    public static void main(String[] args) {
        OrderFacade f = new OrderFacade();
        System.out.println("order book 50:");
        System.out.println("result=" + f.placeOrder("book", 50));
        System.out.println("order laptop 5000:");
        System.out.println("result=" + f.placeOrder("laptop", 5000));
    }
}

