public class Main {
    static int loads = 0; // counts expensive loads

    interface Image { String show(); }

    static class RealImage implements Image {
        private final String name;
        RealImage(String name) { this.name = name; loads++; } // expensive work happens here
        public String show() { return "drawing " + name; }
    }

    // Virtual proxy: creates the real image only on first use.
    static class LazyImage implements Image {
        private final String name; private RealImage real;
        LazyImage(String name) { this.name = name; }
        public String show() {
            if (real == null) real = new RealImage(name);
            return real.show();
        }
    }

    // Protection proxy: checks the caller's role before delegating.
    static class GuardedImage implements Image {
        private final Image inner; private final String role;
