public class Main {
    // Component: leaves and folders both answer size().
    interface Node { String name(); long size(); }

    static class File implements Node {
        private final String name; private final long bytes;
        File(String name, long bytes) { this.name = name; this.bytes = bytes; }
        public String name() { return name; }
        public long size() { return bytes; }
    }

