        private final String name; private final List<Node> children = new ArrayList<>();
        Folder(String name) { this.name = name; }
        Folder add(Node n) { children.add(n); return this; } // "safe" design: add only on Folder
        public String name() { return name; }
        public long size() {
            long total = 0;
            for (Node c : children) total += c.size(); // recursion, no instanceof
            return total;
        }
    }

