#include <bits/stdc++.h>
using namespace std;

// Component: leaves and folders both answer size().
struct Node {
    string name;
    Node(string n) : name(n) {}
    virtual long long size() = 0;
    virtual ~Node() = default;
};

struct File : Node {
    long long bytes;
    File(string n, long long b) : Node(n), bytes(b) {}
    long long size() override { return bytes; }
};

struct Folder : Node {
    vector<Node*> children;
    Folder(string n) : Node(n) {}
    Folder& add(Node* n) { children.push_back(n); return *this; } // "safe" design: add only on Folder
    long long size() override {
        long long total = 0;
        for (Node* c : children) total += c->size(); // recursion, no dynamic_cast
        return total;
    }
};

int main() {
    File b("b.txt", 250), c("c.txt", 50), p("p.png", 600), a("a.txt", 100);
    Folder docs("docs"), img("img"), root("root");
    docs.add(&b).add(&c);
    img.add(&p);
    root.add(&a).add(&docs).add(&img);
    for (Node* n : {(Node*)&docs, (Node*)&img, (Node*)&root})
        cout << n->name << " size=" << n->size() << endl;
}

