using System;
using System.Collections.Generic;

class Program
{
    // Component: leaves and folders both answer Size().
    interface INode { string Name { get; } long Size(); }

    class File : INode
    {
        private readonly long bytes;
        public string Name { get; private set; }
        public File(string name, long bytes) { Name = name; this.bytes = bytes; }
        public long Size() { return bytes; }
    }

    class Folder : INode
    {
        private readonly List<INode> children = new List<INode>();
        public string Name { get; private set; }
        public Folder(string name) { Name = name; }
        public Folder Add(INode n) { children.Add(n); return this; } // "safe" design: add only on Folder
        public long Size()
        {
            long total = 0;
            foreach (INode c in children) total += c.Size(); // recursion, no type checks
            return total;
        }
    }

    static void Main()
    {
        Folder docs = new Folder("docs").Add(new File("b.txt", 250)).Add(new File("c.txt", 50));
        Folder img = new Folder("img").Add(new File("p.png", 600));
        Folder root = new Folder("root").Add(new File("a.txt", 100)).Add(docs).Add(img);
        foreach (INode n in new INode[] { docs, img, root })
            Console.WriteLine(n.Name + " size=" + n.Size());
    }
}

