public class Main {
    // Implementor hierarchy: HOW the message is delivered.
    interface Channel { String send(String text); }
    static class Email implements Channel { public String send(String t) { return "email:" + t; } }
    static class Sms implements Channel { public String send(String t) { return "sms:" + t; } }

    // Abstraction hierarchy: WHAT is sent. It holds a Channel (the bridge).
    static abstract class Notification {
        protected final Channel channel;
        Notification(Channel channel) { this.channel = channel; }
        abstract String notifyUser(String text);
    }
    static class Alert extends Notification {
        Alert(Channel c) { super(c); }
        String notifyUser(String t) { return channel.send("ALERT " + t); }
    }
    static class Promo extends Notification {
        Promo(Channel c) { super(c); }
        String notifyUser(String t) { return channel.send("PROMO " + t); }
    }

    public static void main(String[] args) {
        Channel[] channels = { new Email(), new Sms() };
        for (Channel c : channels) {
            System.out.println(new Alert(c).notifyUser("disk full"));
            System.out.println(new Promo(c).notifyUser("50% off"));
        }
        int m = 3, n = 4; // 3 kinds of message, 4 channels
        System.out.println("subclasses without bridge=" + m * n + ", with bridge=" + (m + n));
    }
}

