using System;

class Program
{
    // Implementor hierarchy: HOW the message is delivered.
    interface IChannel { string Send(string text); }
    class Email : IChannel { public string Send(string t) { return "email:" + t; } }
    class Sms : IChannel { public string Send(string t) { return "sms:" + t; } }

    // Abstraction hierarchy: WHAT is sent. It holds a channel (the bridge).
    abstract class Notification
    {
        protected readonly IChannel channel;
        protected Notification(IChannel channel) { this.channel = channel; }
        public abstract string Notify(string text);
    }
    class Alert : Notification
    {
        public Alert(IChannel c) : base(c) { }
        public override string Notify(string t) { return channel.Send("ALERT " + t); }
    }
    class Promo : Notification
    {
        public Promo(IChannel c) : base(c) { }
        public override string Notify(string t) { return channel.Send("PROMO " + t); }
    }

    static void Main()
    {
        foreach (IChannel c in new IChannel[] { new Email(), new Sms() })
        {
            Console.WriteLine(new Alert(c).Notify("disk full"));
            Console.WriteLine(new Promo(c).Notify("50% off"));
        }
        int m = 3, n = 4; // 3 kinds of message, 4 channels
        Console.WriteLine("subclasses without bridge=" + m * n + ", with bridge=" + (m + n));
    }
