import java.util.*;

public class Main {
    // Flyweight: intrinsic state (shared, immutable).
    static final class TreeType {
        final String species; final int textureMb;
        TreeType(String species, int textureMb) { this.species = species; this.textureMb = textureMb; }
    }

    // Factory: hands out one shared TreeType per species.
    static class TreeFactory {
        private final Map<String, TreeType> pool = new HashMap<>();
        TreeType get(String species) { return pool.computeIfAbsent(species, s -> new TreeType(s, 2)); }
        int size() { return pool.size(); }
    }

    // Context: extrinsic state (x, y) plus a reference to the shared flyweight.
    static class Tree {
        final int x, y; final TreeType type;
        Tree(int x, int y, TreeType type) { this.x = x; this.y = y; this.type = type; }
    }

    public static void main(String[] args) {
        String[] species = { "oak", "pine", "birch" };
        TreeFactory factory = new TreeFactory();
        List<Tree> forest = new ArrayList<>();
        for (int i = 0; i < 1000; i++) forest.add(new Tree(i, i * 2, factory.get(species[i % 3])));
        System.out.println("trees=" + forest.size() + " distinct types=" + factory.size());
        System.out.println("tree 0 and tree 3 share type: " + (forest.get(0).type == forest.get(3).type ? "yes" : "no"));
        System.out.println("texture MB naive=" + forest.size() * 2 + " shared=" + factory.size() * 2);
    }
}

