using System;
using System.Collections.Generic;

class Program
{
    // Flyweight: intrinsic state (shared, immutable).
    class TreeType
    {
        public readonly string Species; public readonly int TextureMb;
        public TreeType(string species, int textureMb) { Species = species; TextureMb = textureMb; }
    }

