            if (!pool.TryGetValue(species, out t)) { t = new TreeType(species, 2); pool[species] = t; }
            return t;
        }
        public int Size { get { return pool.Count; } }
    }

    // Context: extrinsic state (x, y) plus a reference to the shared flyweight.
    class Tree
    {
        public readonly int X, Y; public readonly TreeType Type;
        public Tree(int x, int y, TreeType type) { X = x; Y = y; Type = type; }
    }

