import java.util.*;

public class Main {
    interface Appender { void append(String line); }

    static class ConsoleAppender implements Appender {
        private final String tag;
        ConsoleAppender(String tag) { this.tag = tag; }
        public void append(String line) { System.out.println("[" + tag + "] " + line); }
    }

    // Composite: many appenders that look like one.
    static class MultiAppender implements Appender {
        private final List<Appender> list = new ArrayList<>();
        MultiAppender add(Appender a) { list.add(a); return this; }
        public void append(String line) { for (Appender a : list) a.append(line); }
    }

    // Decorator: wraps one appender and only forwards ERROR lines.
    static class ErrorsOnly implements Appender {
        private final Appender inner;
        ErrorsOnly(Appender inner) { this.inner = inner; }
        public void append(String line) { if (line.contains(" ERROR ")) inner.append(line); }
    }

    // Bridge: Logger (levels, names) holds an Appender (output).
    static class Logger {
        static final String[] NAMES = { "DEBUG", "INFO", "ERROR" };
        private final String name; private final Appender out; private final int minLevel;
        Logger(String name, Appender out, int minLevel) { this.name = name; this.out = out; this.minLevel = minLevel; }
        void log(int level, String msg) {
            if (level < minLevel) return;                       // check level before formatting
            out.append(name + " " + NAMES[level] + " " + msg);
        }
    }

    public static void main(String[] args) {
        Appender out = new MultiAppender().add(new ConsoleAppender("stdout")).add(new ErrorsOnly(new ConsoleAppender("alerts")));
        Logger log = new Logger("orders", out, 1);
        log.log(0, "cache miss");   // DEBUG is below INFO: dropped
        log.log(1, "created");
        log.log(2, "failed");
    }
}

