#include <bits/stdc++.h>
using namespace std;

struct Appender {
    virtual void append(const string& line) = 0;
    virtual ~Appender() = default;
};

struct ConsoleAppender : Appender {
    string tag;
    ConsoleAppender(string t) : tag(t) {}
    void append(const string& line) override { cout << "[" << tag << "] " << line << endl; }
};

// Composite: many appenders that look like one.
struct MultiAppender : Appender {
    vector<Appender*> items;
    MultiAppender& add(Appender* a) { items.push_back(a); return *this; }
    void append(const string& line) override { for (auto* a : items) a->append(line); }
};

// Decorator: wraps one appender and only forwards ERROR lines.
struct ErrorsOnly : Appender {
    Appender& inner;
    ErrorsOnly(Appender& i) : inner(i) {}
    void append(const string& line) override {
        if (line.find(" ERROR ") != string::npos) inner.append(line);
    }
};

// Bridge: Logger (levels, names) holds an appender (output).
struct Logger {
    string name; Appender& out; int minLevel;
    Logger(string n, Appender& o, int m) : name(n), out(o), minLevel(m) {}
    void log(int level, const string& msg) {
        static const char* NAMES[] = {"DEBUG", "INFO", "ERROR"};
        if (level < minLevel) return; // check level before formatting
        out.append(name + " " + NAMES[level] + " " + msg);
    }
};

int main() {
    ConsoleAppender stdoutA("stdout"), alertsA("alerts");
    ErrorsOnly errors(alertsA);
    MultiAppender out;
    out.add(&stdoutA).add(&errors);
    Logger log("orders", out, 1);
    log.log(0, "cache miss"); // DEBUG is below INFO: dropped
    log.log(1, "created");
    log.log(2, "failed");
}

