using System;
using System.Collections.Generic;

class Program
{
    interface IAppender { void Append(string line); }

    class ConsoleAppender : IAppender
    {
        private readonly string tag;
        public ConsoleAppender(string tag) { this.tag = tag; }
        public void Append(string line) { Console.WriteLine("[" + tag + "] " + line); }
    }

    // Composite: many appenders that look like one.
    class MultiAppender : IAppender
    {
        private readonly List<IAppender> list = new List<IAppender>();
        public MultiAppender Add(IAppender a) { list.Add(a); return this; }
        public void Append(string line) { foreach (IAppender a in list) a.Append(line); }
    }

    // Decorator: wraps one appender and only forwards ERROR lines.
    class ErrorsOnly : IAppender
    {
        private readonly IAppender inner;
        public ErrorsOnly(IAppender inner) { this.inner = inner; }
        public void Append(string line) { if (line.Contains(" ERROR ")) inner.Append(line); }
    }

    // Bridge: Logger (levels, names) holds an appender (output).
    class Logger
    {
        static readonly string[] Names = { "DEBUG", "INFO", "ERROR" };
        private readonly string name; private readonly IAppender output; private readonly int minLevel;
        public Logger(string name, IAppender output, int minLevel) { this.name = name; this.output = output; this.minLevel = minLevel; }
        public void Log(int level, string msg)
        {
            if (level < minLevel) return; // check level before formatting
            output.Append(name + " " + Names[level] + " " + msg);
        }
    }

    static void Main()
    {
        IAppender o = new MultiAppender().Add(new ConsoleAppender("stdout")).Add(new ErrorsOnly(new ConsoleAppender("alerts")));
        Logger log = new Logger("orders", o, 1);
        log.Log(0, "cache miss"); // DEBUG is below INFO: dropped
        log.Log(1, "created");
        log.Log(2, "failed");
    }
}

