import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    static final AtomicInteger loads = new AtomicInteger();

    static class Report { final int value; Report(int v) { value = v; } }

    // Thread-safe lazy proxy: double-checked locking.
    static class LazyReport {
        private volatile Report real; // volatile: other threads see a fully built object
        Report get() {
            Report r = real;                       // first check, no lock
            if (r == null) {
                synchronized (this) {
                    r = real;                      // second check, inside the lock
                    if (r == null) {
                        loads.incrementAndGet();
                        try { Thread.sleep(50); } catch (InterruptedException e) { }  // slow load
                        r = new Report(42);
                        real = r;
                    }
                }
            }
            return r;
        }
    }

    public static void main(String[] args) throws Exception {
        LazyReport proxy = new LazyReport();
        int[] results = new int[4];
        Thread[] ts = new Thread[4];
        for (int i = 0; i < 4; i++) {
            final int idx = i;
            ts[i] = new Thread(() -> results[idx] = proxy.get().value);
            ts[i].start();
        }
        int sum = 0;
        for (int i = 0; i < 4; i++) { ts[i].join(); sum += results[i]; }
        System.out.println("sum of 4 results=" + sum + " loads=" + loads.get());
    }
}

