import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    static final AtomicInteger backendCalls = new AtomicInteger();

    static int backend(String key) throws InterruptedException {
        backendCalls.incrementAndGet();
        Thread.sleep(100);   // slow backend
        return 99;
    }

    static final ConcurrentHashMap<String, CompletableFuture<Integer>> cache = new ConcurrentHashMap<>();

    // Single-flight: store the FUTURE; only the thread that installed it calls the backend.
    static int get(String key) throws Exception {
        boolean[] mine = { false };
        CompletableFuture<Integer> f = cache.computeIfAbsent(key, k -> { mine[0] = true; return new CompletableFuture<>(); });
        if (mine[0]) {
            try { f.complete(backend(key)); }                                    // load outside the map lock
            catch (Exception e) { cache.remove(key); f.completeExceptionally(e); } // do not cache failures
        }
        return f.join();                                                          // everyone else waits here
    }

    public static void main(String[] args) throws Exception {
        int[] results = new int[5];
        Thread[] ts = new Thread[5];
        for (int i = 0; i < 5; i++) {
            final int idx = i;
            ts[i] = new Thread(() -> { try { results[idx] = get("fx"); } catch (Exception e) { } });
            ts[i].start();
        }
        int sum = 0;
        for (int i = 0; i < 5; i++) { ts[i].join(); sum += results[i]; }
        System.out.println("5 callers, sum=" + sum + ", backend calls=" + backendCalls.get());
    }
}

