using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static int backendCalls = 0;
    static readonly object gate = new object();
    static readonly Dictionary<string, TaskCompletionSource<int>> cache = new Dictionary<string, TaskCompletionSource<int>>();

    static int Backend(string key)
    {
        Interlocked.Increment(ref backendCalls);
        Thread.Sleep(100); // slow backend
        return 99;
    }

    // Single-flight: store the task source; only the thread that installed it calls the backend.
    static int Get(string key)
    {
        TaskCompletionSource<int> tcs;
        bool mine = false;
        lock (gate)
        {
            if (!cache.TryGetValue(key, out tcs))
            {
                tcs = new TaskCompletionSource<int>();
                cache[key] = tcs;
                mine = true;
            }
        }
        if (mine)
        {
            try { tcs.SetResult(Backend(key)); }                     // load outside the lock
            catch (Exception e) { lock (gate) { cache.Remove(key); } tcs.SetException(e); } // do not cache failures
        }
        return tcs.Task.Result;                                      // everyone else waits here
    }

    static void Main()
    {
        int[] results = new int[5];
        Thread[] ts = new Thread[5];
        for (int i = 0; i < 5; i++)
        {
            int idx = i;
            ts[i] = new Thread(() => { results[idx] = Get("fx"); });
            ts[i].Start();
        }
        int sum = 0;
        for (int i = 0; i < 5; i++) { ts[i].Join(); sum += results[i]; }
        Console.WriteLine("5 callers, sum=" + sum + ", backend calls=" + backendCalls);
    }
}

