public class Main {
    interface Model { String complete(String prompt); }

    // Fake provider: fails on its first two calls, then answers.
    static class FakeModel implements Model {
        private int calls = 0;
        public String complete(String prompt) {
            calls++;
            if (calls < 3) { System.out.println("model call " + calls + " failed"); throw new RuntimeException("timeout"); }
            System.out.println("model call " + calls + " ok");
            return "echo:" + prompt;
        }
    }

    // Decorator 1: retry up to N attempts.
    static class Retry implements Model {
        private final Model inner; private final int attempts;
        Retry(Model inner, int attempts) { this.inner = inner; this.attempts = attempts; }
        public String complete(String prompt) {
            for (int i = 1; ; i++) {
                try { return inner.complete(prompt); }
                catch (RuntimeException e) { if (i >= attempts) throw e; }
            }
        }
    }

    // Decorator 2: redact phone numbers BEFORE anything else sees the prompt.
    static class Redact implements Model {
        private final Model inner;
        Redact(Model inner) { this.inner = inner; }
        public String complete(String prompt) { return inner.complete(prompt.replace("555-1234", "[PHONE]")); }
    }

    public static void main(String[] args) {
        Model model = new Redact(new Retry(new FakeModel(), 3)); // order matters: redact is outermost
        String prompt = "call me at 555-1234";
        System.out.println("prompt: " + prompt);
        System.out.println("reply: " + model.complete(prompt));
    }
}

