#include <bits/stdc++.h>
using namespace std;

struct Model {
    virtual string complete(const string& prompt) = 0;
    virtual ~Model() = default;
};

// Fake provider: fails on its first two calls, then answers.
struct FakeModel : Model {
    int calls = 0;
    string complete(const string& prompt) override {
        calls++;
        if (calls < 3) { cout << "model call " << calls << " failed" << endl; throw runtime_error("timeout"); }
        cout << "model call " << calls << " ok" << endl;
        return "echo:" + prompt;
    }
};

// Decorator 1: retry up to N attempts.
struct Retry : Model {
    Model& inner; int attempts;
    Retry(Model& m, int a) : inner(m), attempts(a) {}
    string complete(const string& prompt) override {
        for (int i = 1;; i++) {
            try { return inner.complete(prompt); }
            catch (const runtime_error&) { if (i >= attempts) throw; }
        }
    }
};

// Decorator 2: redact phone numbers BEFORE anything else sees the prompt.
struct Redact : Model {
    Model& inner;
    Redact(Model& m) : inner(m) {}
    string complete(const string& prompt) override {
        string p = prompt;
        size_t pos = p.find("555-1234");
        if (pos != string::npos) p.replace(pos, 8, "[PHONE]");
        return inner.complete(p);
    }
};

int main() {
    FakeModel fake; Retry retry(fake, 3); Redact model(retry); // order matters: redact is outermost
    string prompt = "call me at 555-1234";
    cout << "prompt: " << prompt << endl;
    string reply = model.complete(prompt); // run first: it prints its own lines
    cout << "reply: " << reply << endl;
}

